def parse_date(text: str) -> date:
    """Read a Calder ``txn_date`` field.  Calder writes day first, ``DD/MM/YYYY``."""
    match = _DATE_PATTERN.match(text.strip())
    if not match:
        raise LedgerParseError(f"Calder date {text!r} is not DD/MM/YYYY")
    day, month, year = (int(part) for part in match.groups())
    try:
        return date(year, month, day)
    except ValueError as exc:
        raise LedgerParseError(f"Calder date {text!r} is not a real date") from exc


